#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  chmod 600 "$ENV_FILE" # it holds keys: readable by this user alone
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the human steps behind the site's report form (#129).
#
# The form on an event page and the About page posts to one Vercel function,
# /api/report (site/api/report.ts), which files the report as an issue with a
# token of its own. That token lives only in the Vercel project's environment,
# never in .env or the repository, and a firewall rule rate-limits the path.
#
#   bash scripts/report-form-setup.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

REPO="WrongerSandwich/kc-events"
TOKEN_NAME="GITHUB_REPORT_TOKEN"
VERCEL_PROJECT_URL="https://vercel.com/wrongersandwichs-projects/kc-events"

banner "KC This Week: report form setup"

# ── Stage 1: the token ─────────────────────────────────────────────────────
stage "GitHub: a token that can only file issues"
say "The function files each report with a fine-grained token for this repository alone."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: kc-this-week report form. Expiration: a year (put a reminder in your calendar to renew it)."
step "Resource owner: WrongerSandwich. Repository access: Only select repositories → $REPO."
step "Permissions → Repository permissions → Issues: Read and write. Leave every other permission at No access"
step "(GitHub adds Metadata: Read-only itself, and that one is fine)."
step "Generate the token and copy it: GitHub shows it once."
note "The token is not saved anywhere by this wizard. It goes straight into Vercel in the next stage."
ask_secret REPORT_TOKEN "Paste the token (checked against GitHub, then forgotten):"
if [[ -z "${REPORT_TOKEN:-}" ]]; then
  warn "no token given"
  SKIPPED+=("make the fine-grained token and set it in Vercel as $TOKEN_NAME")
elif command -v curl >/dev/null 2>&1; then
  STATUS=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 15 "https://api.github.com/repos/$REPO/issues?per_page=1" \
    -H "Authorization: Bearer $REPORT_TOKEN" -H "Accept: application/vnd.github+json" 2>/dev/null || echo "000")
  if [[ "$STATUS" == "200" ]]; then
    printf '  %s✓ the token reads %s'"'"'s issues%s\n' "$GREEN" "$REPO" "$RESET"
  else
    warn "GitHub answered $STATUS to the token; check its repository and the Issues permission"
    SKIPPED+=("a token that GitHub accepts for $REPO's issues (it answered $STATUS)")
  fi
  pause "Keep the token on your clipboard and press Enter."
fi

# ── Stage 2: the Vercel environment variable ───────────────────────────────
stage "Vercel: the token as $TOKEN_NAME"
say "Only the function reads it, at request time; the build never does (a test greps the build for it)."
open_url "$VERCEL_PROJECT_URL/settings/environment-variables"
step "Add a variable. Key: $TOKEN_NAME. Value: the token."
step "Environments: Production and Preview (not Development: a local build has no use for it)."
step "Turn on Sensitive, so the value can't be read back from the dashboard."
step "Save."
note "A deployment picks up a variable only when it builds: the PR's preview needs a redeploy (Deployments →"
note "the PR's latest preview → ⋯ → Redeploy), and production gets it on the merge."
confirm "Is $TOKEN_NAME saved for Production and Preview?" || SKIPPED+=("set $TOKEN_NAME in Vercel (Production and Preview, Sensitive)")
unset REPORT_TOKEN

# ── Stage 3: the firewall rule ─────────────────────────────────────────────
stage "Vercel Firewall: rate-limit /api/report"
say "Anyone can post the form, so the path gets a rate limit: a flood is refused at Vercel's edge"
say "before it reaches the function or the GitHub API."
open_url "$VERCEL_PROJECT_URL/firewall"
step "Configure (or Edit rules) → New rule. Name: report form rate limit."
step "If: Request Path, equals, /api/report."
step "Then: Rate Limit. Fixed window, keyed on IP. Suggested: 5 requests per 10 minutes, or the"
step "longest window your plan offers with about that many requests. Action when exceeded: Deny (429)."
step "Save the rule, then Review changes → Publish."
note "Not sure your plan offers this window? Pick what it allows: any limit is far better than none."
confirm "Is the rule published?" || SKIPPED+=("publish a Vercel Firewall rate-limit rule on /api/report")

# ── Stage 4: try it on the preview ─────────────────────────────────────────
stage "Try it on the pull request's preview"
say "Open the PR's Vercel preview (the link in the PR's Vercel comment), redeployed after stage 2."
step "Open any event's page, click 'Wrong? Report it', write 'Test from the report form, please close',"
step "and send. It should say 'Sent. Thanks.'"
step "Optional: turn JavaScript off in the browser and send one from the About page: you should land on"
step "a plain page that says 'Sent. Thanks.'"
pause "Press Enter once it says Sent, and this wizard will look for the issue."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "Newest issues labelled needs-triage:"
  gh issue list --repo "$REPO" --label needs-triage --limit 3 --json number,title,labels \
    --template '{{range .}}    #{{.number}} {{.title}}  [{{range $i, $l := .labels}}{{if $i}}, {{end}}{{$l.name}}{{end}}]{{"\n"}}{{end}}' || true
  if confirm "Is the test report there, titled 'Wrong listing: …' and labelled bug and needs-triage?"; then
    ask TEST_ISSUE "Its issue number, to close it (Enter to leave it open):"
    if [[ -n "${TEST_ISSUE:-}" ]]; then
      gh issue close "$TEST_ISSUE" --repo "$REPO" --reason "not planned" --comment "Test of the report form (#129)." >/dev/null \
        && printf '  %s✓ closed%s #%s\n' "$GREEN" "$RESET" "$TEST_ISSUE"
    fi
  else
    SKIPPED+=("a test report from the preview: check the function's logs in Vercel (Logs, path /api/report)")
  fi
else
  SKIPPED+=("check the test report landed in $REPO's issues with bug and needs-triage, then close it")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
say "Once the preview works, the PR can merge; production picks up the token on that deploy."
printf '\n'
